/**
 * Enumeration of node alignment options. To be accessed using `CoreOptions.ALIGNMENT`.
 */
package enum Alignment {
    /// automatic alignment (default).
    case automatic
    /// left alignment.
    case left
    /// right alignment.
    case right
    /// top alignment.
    case top
    /// bottom alignment.
    case bottom
    /// center alignment.
    case center
}
